const fs = require('fs');
const data = fs.readFileSync(0, 'utf8').trim().split(/\s+/);

let idx = 0;
const N = Number(data[idx++]);
const X1 = BigInt(data[idx++]);
const X2 = BigInt(data[idx++]);

const pts = new Array(N);

for (let i = 0; i < N; i++) {
  const A = BigInt(data[idx++]);
  const B = BigInt(data[idx++]);
  pts[i] = {
    u: A * X1 + B,
    v: A * X2 + B
  };
}

pts.sort((p, q) => {
  if (p.u < q.u) return -1;
  if (p.u > q.u) return 1;
  if (p.v > q.v) return -1;
  if (p.v < q.v) return 1;
  return 0;
});

const vals = pts.map(p => p.v).sort((a, b) => (a < b ? -1 : a > b ? 1 : 0));
const uniq = [];

for (let i = 0; i < vals.length; i++) {
  if (i === 0 || vals[i] !== vals[i - 1]) uniq.push(vals[i]);
}

const rank = new Map();
for (let i = 0; i < uniq.length; i++) {
  rank.set(uniq[i], i + 1);
}

const M = uniq.length;
const bit = new Array(M + 1).fill(0);

function add(i) {
  for (; i <= M; i += i & -i) bit[i]++;
}

function sum(i) {
  let s = 0;
  for (; i > 0; i -= i & -i) s += bit[i];
  return s;
}

let ans = 0;

for (let i = 0; i < N; i++) {
  const r = rank.get(pts[i].v);
  ans += i - sum(r - 1);
  add(r);
}

console.log(ans);
